// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    address actor;

    function setUp() public {
        c = new Roulette{value: 10 ether}();
        actor = address(0xABCD);
        vm.deal(actor, 100 ether);
    }

    function testFuzz_property(uint256 t1, uint256 t2) public {
        t1 = bound(t1, 1, type(uint64).max);
        t2 = bound(t2, 1, type(uint64).max);

        vm.warp(t1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1, "first call must succeed at t1 > 0");

        vm.warp(t2);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // General rule: any two SUCCESSFUL fallback calls must have happened at
        // different timestamps (pastBlockTime is bumped each call).
        assertTrue(!(ok1 && ok2) || (t1 != t2), "two successful calls cannot share a timestamp");
    }
}
